using System;using System.IO;using System.Collections.Generic;using LestingCraft.Story;using LestingCraft.World;using LestingCraft.Gameplay;
public static class CheckStoryCore
{
 static int checks;static void Check(bool b,string label){checks++;if(!b)throw new Exception(label);}static uint rng=99371;static int Next(int max){rng=unchecked(rng*1664525+1013904223);return (int)(rng%(uint)max);}
 static int Lines(int stage)=>stage==3?21:stage==5?18:stage==7?8:stage==9?12:stage==13?15:0;
 static void Main(string[] args)
 {
  var inv=new Inventory();inv.Add(148,6);Check(inv.ToggleOffhand(),"equip torch");Check(inv.offhand.count==1&&inv.Count(148)==5,"one torch only");Check(inv.Clone().offhand.item==148,"cloned offhand");Check(inv.ExtraStacks().Length==22,"death includes torch");Check(inv.ToggleOffhand()&&inv.Count(148)==6,"return torch");inv.cursor=new ItemStack{item=148,count=6};InventoryInteraction.Click(inv,66,false,false);Check(inv.offhand.count==1&&inv.cursor.count==5,"UI only transfers one");int total=12; // six in bag, five cursor, one offhand
  for(int i=0;i<15000;i++){InventoryInteraction.Click(inv,Next(67),Next(2)==0,Next(4)==0);int n=0;foreach(var x in inv.slots)n+=x.count;foreach(var x in inv.ExtraStacks())n+=x.count;Check(n==total,"conservation including slot66");Check(inv.offhand.count<=1,"offhand max1");}
  var recipe=CraftingTable.All[CraftingTable.All.Length-1];inv=new Inventory();inv.Add(123,1);inv.Add(121,1);Check(CraftingTable.Fill(inv,recipe,2),"torch2x2");Check(CraftingTable.Take(inv,2,true)==4&&inv.Count(148)==4,"four torches from coal+stick");
  var terrain=new List<string>();int[] seeds={2506,1,-17,int.MinValue,int.MaxValue};int[,] anchors={{-32,-32},{0,8},{96,48},{48,-96},{176,-112}};
  for(int i=0;i<12000;i++){int seed=seeds[i%5],a=i%5,x=anchors[a,0]+Next(65)-32,z=anchors[a,1]+Next(65)-32,y=StoryWorld.Floor(seed)-5+Next(27);ushort id=TerrainGenerator.SampleContent(x,y,z,seed,Dimension.Lestingia,4);terrain.Add("["+x+","+y+","+z+","+seed+","+id+"]");Check(id<=46,"known block");Check(TerrainGenerator.SampleContent(x,0,z,seed,Dimension.Lestingia,4)==9,"bedrock");}
  Check(TerrainGenerator.SampleContent(-32,StoryWorld.Floor(2506),-32,2506,Dimension.Lestingia,4)==36,"authored floor");Check(TerrainGenerator.SampleContent(-3,StoryWorld.Floor(2506),8,2506,Dimension.Lestingia,4)!=0,"weight platform");
  var rows=new List<string>();string[] actions={"ready","crate","satchel","witness","weight","village","mill","rune","smith","altar","choice","ack","pylon","hit"};long now=100000;
  for(int i=0;i<16000;i++){var s=new StoryState{stage=Next(15),line=Next(24)-1,bridgeMask=Next(8),bridgeSolved=Next(2)==0,searched=Next(4),runes=Next(3),choice=Next(3),rewards=Next(16),bossHealth=Next(181),bossPhase=Next(2),pylons=Next(8),sceneAt=now-Next(20000),vulnerableUntil=now+Next(30000)-15000};var before=Fields(s);string action=actions[Next(actions.Length)];int arg=Next(5)-1;bool changed=i%3==0?StoryRules.Tick(s,now):StoryRules.Act(s,action,arg,now,Lines(s.stage));rows.Add("{\"before\":"+before+",\"action\":\""+(i%3==0?"tick":action)+"\",\"arg\":"+arg+",\"changed\":"+(changed?"true":"false")+",\"after\":"+Fields(s)+"}");}
  File.WriteAllText(args[0],"{\"terrain\":["+string.Join(",",terrain)+"],\"reducers\":["+string.Join(",",rows)+"]}");Console.WriteLine("PASS "+checks+" C# assertions, 15000 randomized inventory operations with offhand, 12000 content4 terrain vectors, 16000 reducer vectors. Managed code only; no native Unity/GPU.");
 }
 static string Fields(StoryState s){return "{\"stage\":"+s.stage+",\"line\":"+s.line+",\"revision\":"+s.revision+",\"searched\":"+s.searched+",\"choice\":"+s.choice+",\"rewards\":"+s.rewards+",\"runes\":"+s.runes+",\"bossHealth\":"+s.bossHealth+",\"bossMax\":"+s.bossMax+",\"bossPhase\":"+s.bossPhase+",\"pylons\":"+s.pylons+",\"sceneAt\":"+s.sceneAt+",\"vulnerableUntil\":"+s.vulnerableUntil+",\"bridgeMask\":"+s.bridgeMask+",\"bridgeSolved\":"+(s.bridgeSolved?"true":"false")+",\"acked\":"+s.acked+"}";}
}
